import sys

def max_symmetric_matrix(n, k):
    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    if k % 2 == 1:
        matrix[n // 2][n // 2] = 1
        k -= 1

    half_k = k // 2
    row = 0
    col = 0

    while half_k > 0:
        if col < n:
            matrix[row][col] = 1
            matrix[col][row] = 1
            half_k -= 1
            col += 1
        else:
            row += 1
            col = row

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])

    result = max_symmetric_matrix(n, k)
    if result != -1:
        print_matrix(result)
    else:
        print(-1)
