import sys

def max_symmetric_matrix(n, k):
    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    if k % 2 == 1:
        k -= 1
        matrix[n // 2][n // 2] = 1

    i, j = 0, 0
    while k > 0:
        if i != j:
            matrix[i][j] = 1
            matrix[j][i] = 1
        else:
            matrix[i][j] = 1

        i += 1
        if i >= n:
            i = 0
            j += 1

        k -= 1

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    result = max_symmetric_matrix(n, k)

    if result == -1:
        print(-1)
    else:
        print_matrix(result)
