import sys

def fill_matrix(n, k):
    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    # Fill the upper triangle including the diagonal
    i = 0
    while k > 0:
        if i >= n:
            break
        j = 0
        while j <= i:
            if k > 0:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 2
            else:
                break
            j += 1
        i += 1

    # If there are still remaining ones, place them on the diagonal
    if k > 0:
        for i in range(k):
            matrix[i][i] = 1

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])

    result = fill_matrix(n, k)
    if result == -1:
        print(-1)
    else:
        print_matrix(result)
