def max_symmetric_matrix(n, k):
    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    # Place ones in the upper triangle including the diagonal
    i, j = 0, 0
    while k > 0:
        if i == j or k % 2 != 0:
            matrix[i][j] = 1
            k -= 1
        i += 1
        if i >= n:
            i = 0
            j += 1

    # Fill the lower triangle based on the upper triangle
    for i in range(1, n):
        for j in range(i):
            matrix[i][j] = matrix[j][i]

    return matrix

