import sys

def create_symmetric_matrix(n, k):
    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    # Place ones in the upper triangle including the diagonal
    ones_to_place = k
    for i in range(n):
        for j in range(i, n):
            if ones_to_place == 0:
                break
            matrix[i][j] = 1
            ones_to_place -= 1

    # Reflect the upper triangle across the diagonal to make the matrix symmetric
    for i in range(1, n):
        for j in range(i):
            matrix[j][i] = matrix[i][j]

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(' '.join(map(str, row)))

