import sys

def max_symmetric_matrix(n, k):
    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    # Place ones in the upper triangle and the diagonal
    i = j = 0
    while k > 0:
        if i == j:
            matrix[i][j] = 1
            k -= 1
        elif i < j:
            matrix[i][j] = 1
            matrix[j][i] = 1
            k -= 2
        i += 1
        if i >= n:
            i = 0
            j += 1

    # If there's still one position left, place it on the diagonal
    if k == 1:
        for i in range(n):
            if matrix[i][i] == 0:
                matrix[i][i] = 1
                break
        else:
            return -1

    return matrix

